import { useState } from 'react';
import type { Book } from './types';

// null = loading in progress; Book[] = data ready (may be empty).
// This distinction lets consumers show a skeleton without a separate isLoading flag.
export function App(): JSX.Element {
  const [books, setBooks] = useState<Book[] | null>(null);

  return <div>{books === null ? 'Loading…' : `${books.length} books`}</div>;
}
